#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;
    vector<int> vals(n);
    for (int i = 0; i < n; ++i) {
        cin >> vals[i];
    }

    vector<int> vals_mod(n);
    for (int i = 0; i < n; ++i) {
        vals_mod[i] = vals[i] % k;
    }

    if (n == 1) {
        cout << vals_mod[0] << "\n";
        return 0;
    }

    vector<int> part_x(vals_mod.begin(), vals_mod.begin() + n / 2);
    vector<int> part_y(vals_mod.begin() + n / 2, vals_mod.end());

    unordered_set<int> set_x, set_y, temp_set_y;

    for (int v : part_x) {
        for (int prev : set_x) {
            set_y.insert((prev + v) % k);
        }
        set_x.insert(v);
        for (int prev : set_y) {
            set_x.insert(prev);
        }
        set_y.clear();
    }

    for (int v : part_y) {
        for (int prev : set_y) {
            set_y.insert((prev + v) % k);
        }
        for (int prev : set_x) {
            set_y.insert(prev);
        }
    }

    vector<int> list_x(set_x.begin(), set_x.end());
    vector<int> list_y(set_y.begin(), set_y.end());

    sort(list_x.begin(), list_x.end());
    sort(list_y.begin(), list_y.end());

    int max_value_found = max(*max_element(list_x.begin(), list_x.end()), *max_element(list_y.begin(), list_y.end()));
    int res = max_value_found;

    for (int s_elem : list_x) {
        int target = k - 1 - s_elem;
        auto it = upper_bound(list_y.begin(), list_y.end(), target);
        if (it != list_y.begin()) {
            int r = *(it - 1);
            int rt = list_y.back();
            int candidate1 = (r + s_elem) % k;
            int candidate2 = (s_elem + rt) % k;
            res = max(res, max(candidate1, candidate2));
        }
    }

    cout << res << "\n";

    return 0;
}
